package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;class RrEvaluationPermissionGuardTest{@Test void requiresAssignedOrAgencyScopeAndExactAction(){var client=mock(AdministrativeAuthorizationClient.class);var guard=new RrEvaluationPermissionGuard(client);when(client.resolve(RrEvaluationPermissionGuard.EVALUATION,"t")).thenReturn(new EffectiveFeaturePermission("f",false,true,false,true,false,false,true,true,false,false,false,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.SUBMIT,"t")).isEqualTo(PermissionDataScope.ASSIGNED_RECORDS);assertThatThrownBy(()->guard.require(RrEvaluationPermissionGuard.EVALUATION,PrimeHrAction.FINALIZE,"t")).isInstanceOf(AccessDeniedException.class);when(client.resolve(RrEvaluationPermissionGuard.ELIGIBILITY,"t")).thenReturn(new EffectiveFeaturePermission("f",false,true,false,true,false,false,true,true,false,false,false,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(RrEvaluationPermissionGuard.ELIGIBILITY,PrimeHrAction.EDIT,"t")).isInstanceOf(AccessDeniedException.class);}}
